import pandas as pd
import numpy as np


def run(inputs: dict[str, "pd.DataFrame"]) -> dict[str, "pd.DataFrame"]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Build dict of current target state keyed by order_id
    # Assume order_id is unique in target_state
    target_state = target_state.drop_duplicates(subset="order_id", keep="first")
    target_map = {}
    for _, row in target_state.iterrows():
        target_map[row["order_id"]] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"],
        }

    # 1. Dedupe events by seq (at-least-once delivery -> apply once)
    events = cdc_events.drop_duplicates(subset="seq", keep="first").copy()

    # 2. Replay guard: skip events whose seq <= target_state's last_seq for that order
    def guard_pass(row):
        oid = row["order_id"]
        if oid in target_map:
            return row["seq"] > target_map[oid]["last_seq"]
        return True

    if len(events) > 0:
        mask = events.apply(guard_pass, axis=1)
        events = events[mask]

    # 3. Sort remaining events by seq within each order and apply in order
    events = events.sort_values(by=["order_id", "seq"], kind="mergesort")

    # Initialize working state copy from target_map (existence flag)
    state = {}
    for oid, v in target_map.items():
        state[oid] = {
            "exists": True,
            "status": v["status"],
            "amount": v["amount"],
            "last_seq": v["last_seq"],
            "last_deleted_seq": None,
        }

    # Ensure all orders referenced by events have an entry
    for oid in events["order_id"].unique():
        if oid not in state:
            state[oid] = {
                "exists": False,
                "status": None,
                "amount": None,
                "last_seq": None,
                "last_deleted_seq": None,
            }

    # Apply events in seq order per order
    for oid, grp in events.groupby("order_id", sort=False):
        grp = grp.sort_values(by="seq", kind="mergesort")
        s = state[oid]
        for _, ev in grp.iterrows():
            op = ev["op"]
            seq = ev["seq"]
            ev_status = ev["status"]
            ev_amount = ev["amount"]

            if op == "I" or op == "U":
                if s["exists"]:
                    new_status = ev_status
                    if op == "U" and pd.isna(ev_amount):
                        new_amount = s["amount"]
                    else:
                        new_amount = ev_amount
                else:
                    new_status = ev_status
                    new_amount = ev_amount

                s["status"] = new_status
                s["amount"] = new_amount
                s["last_seq"] = seq
                s["exists"] = True
                s["last_deleted_seq"] = None
            elif op == "D":
                if s["exists"]:
                    s["exists"] = False
                    s["last_deleted_seq"] = seq
                    s["status"] = None
                    s["amount"] = None
                    s["last_seq"] = None
                # else: no-op, D on missing order does nothing
        state[oid] = s

    # 4. Build new_state output
    new_state_rows = []
    tombstone_rows = []

    for oid, s in state.items():
        if s["exists"]:
            new_state_rows.append(
                {
                    "order_id": oid,
                    "status": s["status"],
                    "amount": s["amount"],
                    "last_seq": s["last_seq"],
                }
            )
        else:
            if s["last_deleted_seq"] is not None:
                tombstone_rows.append(
                    {
                        "order_id": oid,
                        "deleted_seq": s["last_deleted_seq"],
                    }
                )

    new_state_df = pd.DataFrame(
        new_state_rows, columns=["order_id", "status", "amount", "last_seq"]
    )
    tombstones_df = pd.DataFrame(
        tombstone_rows, columns=["order_id", "deleted_seq"]
    )

    # Try to coerce dtypes similar to inputs where possible
    if len(new_state_df) > 0:
        try:
            new_state_df["order_id"] = new_state_df["order_id"].astype(
                target_state["order_id"].dtype
                if "order_id" in target_state.columns
                else cdc_events["order_id"].dtype
            )
        except Exception:
            pass
        try:
            new_state_df["last_seq"] = new_state_df["last_seq"].astype(
                cdc_events["seq"].dtype
            )
        except Exception:
            pass

    if len(tombstones_df) > 0:
        try:
            tombstones_df["order_id"] = tombstones_df["order_id"].astype(
                cdc_events["order_id"].dtype
            )
        except Exception:
            pass
        try:
            tombstones_df["deleted_seq"] = tombstones_df["deleted_seq"].astype(
                cdc_events["seq"].dtype
            )
        except Exception:
            pass

    return {"new_state": new_state_df, "tombstones": tombstones_df}
